131	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
132		repo, err := strategy.OpenRepository(ctx)
133		if err != nil {
134			cmd.SilenceUsage = true
135			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
136			return NewSilentError(err)
137		}
138	
139		v1Store := checkpoint.NewGitStore(repo)
140		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
141		out := cmd.OutOrStdout()
142		progressOut := cmd.ErrOrStderr()
143	
144		result, freshlyPackedRefs, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, progressOut, force)
145		if err != nil {
146			return err
147		}
148	
149		// Skip the generation-metadata repair pass on no-op reruns: it does a
150		// `git ls-remote` plus a transcript-blob walk per archived /full/<n>,
151		// minutes on big repos. When we did write archives, freshly-packed refs
152		// are excluded — their generation.json is already correct from
153		// AggregateTranscriptTimestamps in the packer.
154		var repairResult *strategy.RepairV2GenerationMetadataResult
155		if len(freshlyPackedRefs) > 0 {
156			stopRepair := startSpinner(cmd.ErrOrStderr(), "Repairing archived generation metadata")
157			var repairErr error
158			repairResult, repairErr = strategy.RepairV2GenerationMetadata(ctx, freshlyPackedRefs)
159			if repairErr != nil {
160				stopRepair(false)
161				return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
162			}
163			stopRepair(true)
164			printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
165		}
166	
167		printMigrateCompletion(out, result)
168		fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
169		fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
170		fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)
171	
172		if result.failed > 0 {
173			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
174		}
175		if repairResult != nil && len(repairResult.Failed) > 0 {
176			fmt.Fprintf(out, "%d archived generation(s) failed metadata repair. Check warnings above for details.\n", len(repairResult.Failed))
177			return NewSilentError(fmt.Errorf("%d archived generation(s) failed metadata repair", len(repairResult.Failed)))
178		}
179	
180		return nil
181	}
