368	// sortMigratableCheckpoints sorts oldest-first so archived generations
369	// preserve chronological order. Zero timestamps sort last; CheckpointID
370	// breaks ties for deterministic reruns.
371	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
372		sort.SliceStable(checkpoints, func(i, j int) bool {
373			left := checkpoints[i].CreatedAt
374			right := checkpoints[j].CreatedAt
375			switch {
376			case left.IsZero() && right.IsZero():
377				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
378			case left.IsZero():
379				return false
380			case right.IsZero():
381				return true
382			case left.Equal(right):
383				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
384			default:
385				return left.Before(right)
386			}
387		})
388	}
