990	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
991		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
992			[]string{shardPrefix},
993			nil,
994			checkpoint.UpdateSubtreeOptions{
995				MergeMode:   checkpoint.MergeKeepExisting,
996				DeleteNames: []string{shardSuffix},
997			},
998		)
999		if err != nil {
1000			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
1001		}
1002		if newRoot == rootTreeHash {
1003			return newRoot, nil
1004		}
1005	
1006		newRootTree, err := repo.TreeObject(newRoot)
1007		if err != nil {
1008			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
1009		}
1010		shardTree, err := newRootTree.Tree(shardPrefix)
1011		if err != nil {
1012			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
1013		}
1014		if len(shardTree.Entries) > 0 {
1015			return newRoot, nil
1016		}
1017	
1018		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
1019			nil,
1020			nil,
1021			checkpoint.UpdateSubtreeOptions{
1022				MergeMode:   checkpoint.MergeKeepExisting,
1023				DeleteNames: []string{shardPrefix},
1024			},
1025		)
1026		if err != nil {
1027			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
1028		}
1029		return prunedRoot, nil
1030	}
