1106	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
1107	// by comparing a full compact (startLine=0) against the scoped compact. The difference
1108	// is the number of compact lines before this checkpoint's data.
1109	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
1110		startLine := m.GetTranscriptStart()
1111		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
1112			return 0
1113		}
1114	
1115		if len(fullCompact) == 0 {
1116			return 0
1117		}
1118	
1119		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
1120			Agent:      string(m.Agent),
1121			CLIVersion: versioninfo.Version,
1122			StartLine:  startLine,
1123		})
1124		if err != nil {
1125			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
1126				slog.String("checkpoint_id", string(m.CheckpointID)),
1127				slog.String("agent", string(m.Agent)),
1128				slog.String("error", err.Error()),
1129			)
1130			return 0
1131		}
1132		if len(scopedCompact) == 0 {
1133			return 0
1134		}
1135	
1136		fullLines := bytes.Count(fullCompact, []byte{'\n'})
1137		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
1138		offset := fullLines - scopedLines
1139		if offset < 0 {
1140			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
1141				slog.String("checkpoint_id", string(m.CheckpointID)),
1142				slog.Int("full_lines", fullLines),
1143				slog.Int("scoped_lines", scopedLines),
1144			)
1145			return 0
1146		}
1147		return offset
1148	}
