126	// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
127	func buildLeafTree(
128		repo *git.Repository,
129		existingTreeHash plumbing.Hash,
130		newEntries []object.TreeEntry,
131		opts UpdateSubtreeOptions,
132	) (plumbing.Hash, error) {
133		if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
134			sorted := make([]object.TreeEntry, len(newEntries))
135			copy(sorted, newEntries)
136			sortTreeEntries(sorted)
137			return storeTree(repo, sorted)
138		}
139	
140		// MergeKeepExisting: read existing tree, merge
141		existingTree, err := repo.TreeObject(existingTreeHash)
142		if err != nil {
143			sorted := make([]object.TreeEntry, len(newEntries))
144			copy(sorted, newEntries)
145			sortTreeEntries(sorted)
146			return storeTree(repo, sorted)
147		}
148	
149		// Build lookup of new entries by name
150		newByName := make(map[string]object.TreeEntry, len(newEntries))
151		for _, e := range newEntries {
152			newByName[e.Name] = e
153		}
154	
155		// Build delete set
156		deleteSet := make(map[string]bool, len(opts.DeleteNames))
157		for _, name := range opts.DeleteNames {
158			deleteSet[name] = true
159		}
160	
161		// Merge: keep existing unless overwritten or deleted
162		merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
163		for _, existing := range existingTree.Entries {
164			if deleteSet[existing.Name] {
165				continue
166			}
167			if replacement, ok := newByName[existing.Name]; ok {
168				merged = append(merged, replacement)
169				delete(newByName, existing.Name)
170			} else {
171				merged = append(merged, existing)
172			}
173		}
174		// Add remaining new entries (ones that didn't replace an existing entry)
175		for _, e := range newEntries {
176			if _, stillNew := newByName[e.Name]; stillNew {
177				merged = append(merged, e)
178			}
179		}
180	
181		sortTreeEntries(merged)
182		return storeTree(repo, merged)
183	}
