301	// updateCommittedMain updates prompts and compact transcript on the /main ref for an existing checkpoint.
302	// Returns the session index for coordination with /full/current.
303	func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
304		refName := plumbing.ReferenceName(paths.V2MainRefName)
305		parentHash, rootTreeHash, err := s.GetRefState(refName)
306		if err != nil {
307			return 0, ErrCheckpointNotFound
308		}
309	
310		basePath := opts.CheckpointID.Path() + "/"
311		checkpointPath := opts.CheckpointID.Path()
312	
313		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
314		if err != nil {
315			return 0, err
316		}
317	
318		rootMetadataPath := basePath + paths.MetadataFileName
319		entry, exists := entries[rootMetadataPath]
320		if !exists {
321			return 0, ErrCheckpointNotFound
322		}
323	
324		summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
325		if err != nil {
326			return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
327		}
328		if len(summary.Sessions) == 0 {
329			return 0, ErrCheckpointNotFound
330		}
331	
332		// Find session index by ID, fall back to latest
333		sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
334		if sessionIndex >= len(summary.Sessions) {
335			// findSessionIndex returns next-available when not found; fall back to latest
336			sessionIndex = len(summary.Sessions) - 1
337			logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
338				slog.String("session_id", opts.SessionID),
339				slog.String("checkpoint_id", string(opts.CheckpointID)),
340				slog.Int("fallback_index", sessionIndex),
341			)
342		}
343	
344		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
345	
346		if len(opts.Prompts) > 0 {
347			promptContent := redact.String(JoinPrompts(opts.Prompts))
348			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
349			if err != nil {
350				return 0, fmt.Errorf("failed to create prompt blob: %w", err)
351			}
352			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
353				Name: sessionPath + paths.PromptFileName,
354				Mode: filemode.Regular,
355				Hash: blobHash,
356			}
357		}
358	
359		// Replace compact transcript if provided
360		if len(opts.CompactTranscript) > 0 {
361			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
362			if err != nil {
363				return 0, fmt.Errorf("failed to create compact transcript blob: %w", err)
364			}
365			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
366				Name: sessionPath + paths.CompactTranscriptFileName,
367				Mode: filemode.Regular,
368				Hash: blobHash,
369			}
370	
371			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
372				return 0, fmt.Errorf("failed to write compact transcript hash: %w", err)
373			}
374	
375			// Keep root checkpoint summary in sync with compact artifact paths.
376			if sessionIndex >= 0 && sessionIndex < len(summary.Sessions) {
377				summary.Sessions[sessionIndex].Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
378				summary.Sessions[sessionIndex].ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
379	
380				summaryBytes, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
381				if err != nil {
382					return 0, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
383				}
384				summaryHash, err := CreateBlobFromContent(s.repo, summaryBytes)
385				if err != nil {
386					return 0, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
387				}
388				entries[rootMetadataPath] = object.TreeEntry{
389					Name: rootMetadataPath,
390					Mode: filemode.Regular,
391					Hash: summaryHash,
392				}
393			}
394		}
395	
396		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
397		if err != nil {
398			return 0, err
399		}
400	
401		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
402		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
403		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
404			return 0, err
405		}
406	
407		return sessionIndex, nil
408	}
