410	// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
411	// on the /full/* ref where that checkpoint session already lives, while
412	// preserving other checkpoints' transcripts in the tree. If the session has no
413	// full-transcript artifacts yet, it writes to /full/current.
414	func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
415		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
416	
417		existing, findErr := s.findFullSessionArtifacts(opts.CheckpointID, sessionIndex)
418		if findErr != nil {
419			return findErr
420		}
421		if existing.Found {
422			refName = existing.RefName
423		}
424	
425		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
426			if err := s.ensureRef(ctx, refName); err != nil {
427				return fmt.Errorf("failed to ensure /full/current ref: %w", err)
428			}
429		}
430	
431		parentHash, rootTreeHash, err := s.GetRefState(refName)
432		if err != nil {
433			return err
434		}
435	
436		basePath := opts.CheckpointID.Path() + "/"
437		checkpointPath := opts.CheckpointID.Path()
438		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
439	
440		// Read existing entries and replace transcript for this checkpoint only
441		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
442		if err != nil {
443			return err
444		}
445	
446		// Ignore precompute if invariants are violated — fall back to fresh chunking.
447		precomputed := opts.PrecomputedBlobs
448		if precomputed != nil && !precomputed.isUsable() {
449			precomputed = nil
450		}
451	
452		// Short-circuit: if the existing raw_transcript_hash.txt already matches
453		// the new transcript's sha256, the existing chunk entries represent the
454		// same content — preserve them and skip chunking + zlib.
455		rawTranscriptPath := sessionPath + paths.V2RawTranscriptFileName
456		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
457		var newContentHash string
458		if precomputed != nil {
459			newContentHash = precomputed.ContentHash
460		} else {
461			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(opts.Transcript.Bytes()))
462		}
463		if existing, ok := entries[rawHashPath]; ok {
464			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
465				if rdr, rerr := blob.Reader(); rerr == nil {
466					existingHash, readErr := io.ReadAll(rdr)
467					_ = rdr.Close()
468					if readErr == nil && string(existingHash) == newContentHash {
469						// Content unchanged — skip tree surgery and ref advance to
470						// avoid a no-op commit on /full/current. The existing ref
471						// already references the correct tree.
472						return nil
473					}
474				}
475			}
476		}
477	
478		// Clear existing transcript artifacts for this session path before writing new ones.
479		// Preserve non-transcript metadata under the same session (e.g., tasks/*).
480		for key := range entries {
481			switch {
482			case key == rawTranscriptPath:
483				delete(entries, key)
484			case strings.HasPrefix(key, rawTranscriptPath+"."):
485				delete(entries, key)
486			case key == rawHashPath:
487				delete(entries, key)
488			}
489		}
490	
491		if err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, precomputed, sessionPath, entries); err != nil {
492			return err
493		}
494	
495		if err := s.writeContentHashFromPrecompute(newContentHash, precomputed, sessionPath, entries); err != nil {
496			return err
497		}
498	
499		// Splice into existing root tree (preserves other checkpoints' transcripts)
500		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
501		if err != nil {
502			return err
503		}
504	
505		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
506		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
507		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
508			return err
509		}
510	
511		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
512			s.rotateCurrentIfNeeded(ctx, newTreeHash)
513		}
514	
515		return nil
516	}
