153	// linePreprocessor transforms a parsed JSONL line before conversion.
154	type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
155	
156	// parsedEntry is an intermediate representation of a JSONL line used during
157	// the two-pass compact conversion.
158	type parsedEntry struct {
159		kind         string // "user" or "assistant"
160		ts           json.RawMessage
161		id           string            // message ID (assistant only)
162		userID       string            // prompt ID (user only, e.g. Claude's promptId)
163		inputTokens  int               // API input tokens (assistant only)
164		outputTokens int               // API output tokens (assistant only)
165		content      json.RawMessage   // stripped assistant content array, or nil
166		userText     string            // extracted user text
167		userImages   []json.RawMessage // image blocks from user messages
168		toolResults  []toolResultEntry // user tool_result entries
169	}
170	
171	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
172	// transcript.jsonl format.
173	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
174		return compactJSONLWith(content, opts, nil)
175	}
176	
177	func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
178		base := newTranscriptLine(opts)
179	
180		// Pass 1: parse all lines into intermediate entries.
181		entries, err := parseJSONLEntries(content, preprocess)
182		if err != nil {
183			return nil, err
184		}
185	
186		// Pass 2: merge and emit.
187		var result []byte
188		for i := 0; i < len(entries); i++ {
189			e := entries[i]
190	
191			switch e.kind {
192			case transcript.TypeAssistant:
193				// Merge consecutive assistant entries with the same message ID.
194				merged := e
195				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
196					i++
197					merged = mergeAssistantEntries(merged, entries[i])
198				}
199	
200				// Look ahead for user tool_result entries to inline.
201				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
202					userEntry := entries[i+1]
203					merged = inlineToolResults(merged, userEntry)
204					i++ // consume the user tool_result entry
205	
206					// If the consumed user entry also had text or image content, emit it
207					// as a separate user line after the assistant.
208					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
209						emitAssistant(&result, base, merged)
210						emitUser(&result, base, userEntry)
211						continue
212					}
213				}
214	
215				if isEmptyContentArray(merged.content) {
216					continue
217				}
218	
219				emitAssistant(&result, base, merged)
220	
221			case transcript.TypeUser:
222				// User entries that are purely tool results were already consumed
223				// by the assistant look-ahead above. If we reach one here it was
224				// not preceded by an assistant with a matching tool_use, so emit
225				// it only if it has text or image content.
226				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
227					continue
228				}
229				emitUser(&result, base, e)
230			}
231		}
232	
233		return result, nil
234	}
235	
236	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
237		line := base
238		line.Type = transcript.TypeAssistant
239		line.TS = e.ts
240		line.ID = e.id
241		line.InputTokens = e.inputTokens
242		line.OutputTokens = e.outputTokens
243		line.Content = e.content
244		appendLine(result, line)
245	}
246	
247	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
248		var blocks []json.RawMessage
249	
250		// Text block (with optional prompt ID).
251		if e.userText != "" || len(e.userImages) == 0 {
252			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
253			if err != nil {
254				return
255			}
256			blocks = append(blocks, b)
257		}
258	
259		// Image blocks passed through verbatim.
260		blocks = append(blocks, e.userImages...)
261	
262		contentJSON, err := json.Marshal(blocks)
263		if err != nil {
264			return
265		}
266	
267		line := base
268		line.Type = transcript.TypeUser
269		line.TS = e.ts
270		line.Content = contentJSON
271		appendLine(result, line)
272	}
273	
274	// appendLine marshals a transcriptLine and appends it (with newline) to result.
275	func appendLine(result *[]byte, line transcriptLine) {
276		b, err := json.Marshal(line)
277		if err != nil {
278			return
279		}
280		*result = append(*result, b...)
281		*result = append(*result, '\n')
282	}
283	
284	// parseJSONLEntries parses all JSONL lines into intermediate entries,
285	// filtering dropped types and malformed lines.
286	func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
287		reader := bufio.NewReader(bytes.NewReader(content))
288		var entries []parsedEntry
289	
290		for {
291			lineBytes, err := reader.ReadBytes('\n')
292			if err != nil && err != io.EOF {
293				return nil, fmt.Errorf("reading JSONL line: %w", err)
294			}
295	
296			if len(bytes.TrimSpace(lineBytes)) > 0 {
297				if e, ok := parseLine(lineBytes, preprocess); ok {
298					entries = append(entries, e)
299				}
300			}
301	
302			if err == io.EOF {
303				break
304			}
305		}
306	
307		return entries, nil
308	}
